import React from 'react';
import { certifications } from '../data/mock';

const Certifications = () => {
    // Basic mapping for specific icons if they exist in the MS stack
    const getIcon = (code) => {
        if (code.includes('AZ-')) return 'cloud';
        if (code.includes('SC-')) return 'security';
        if (code.includes('AI-')) return 'smart_toy';
        return 'verified';
    };

    return (
        <section className="py-24 bg-surface-container-low" id="certs">
            <div className="max-w-7xl mx-auto px-6">
                <div className="text-center md:text-left mb-12">
                    <h2 className="font-headline text-3xl md:text-4xl font-bold mb-4">Verified <span className="text-secondary">Expertise</span></h2>
                    <p className="text-on-surface-variant max-w-2xl">Professional certifications validating my expertise in Microsoft technologies and cloud services.</p>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {certifications.map((cert) => (
                        <div key={cert.id} className="p-8 rounded-xl glass-panel border border-white/5 flex flex-col gap-6 hover:-translate-y-2 transition-transform duration-300">
                            <div className="flex items-start justify-between">
                                <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-primary/20 to-primary-container/5 border border-primary/20 flex items-center justify-center text-primary shadow-[0_0_15px_rgba(0,240,255,0.1)]">
                                    <span className="material-symbols-outlined text-3xl">
                                        {getIcon(cert.code)}
                                    </span>
                                </div>
                                <span className="px-3 py-1 bg-surface-container-highest rounded-full text-xs font-bold font-mono tracking-wider text-on-surface-variant border border-white/5">
                                    {cert.code}
                                </span>
                            </div>
                            
                            <div>
                                <h4 className="font-bold text-xl mb-2 text-on-surface leading-snug">{cert.name}</h4>
                                <p className="text-on-surface-variant text-sm flex items-center gap-2 mb-4">
                                    <span className="material-symbols-outlined text-[16px]">apartment</span> {cert.issuer}
                                </p>
                                
                                <p className="text-on-surface-variant text-sm leading-relaxed mb-6">
                                    {cert.description}
                                </p>
                            </div>

                            {cert.skills && cert.skills.length > 0 && (
                                <div className="mt-auto">
                                    <h5 className="text-xs uppercase tracking-widest text-on-surface-variant/70 font-bold mb-3">Core Competencies</h5>
                                    <div className="flex flex-wrap gap-2">
                                        {cert.skills.slice(0, 4).map((skill, sIdx) => (
                                            <span key={sIdx} className="text-[11px] px-2.5 py-1 bg-white/5 rounded border border-white/5 text-on-surface-variant">
                                                {skill}
                                            </span>
                                        ))}
                                        {cert.skills.length > 4 && (
                                            <span className="text-[11px] px-2.5 py-1 text-primary">
                                                +{cert.skills.length - 4} more
                                            </span>
                                        )}
                                    </div>
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default Certifications;
